use vstd::prelude::*;

verus! {
    /// Function to append a value to a vector
    fn append(a: &Vec<i32>, b: i32) -> Vec<i32>
        ensures
            result.len() == a.len() + 1, // The length of the returned vector is one more than the input vector
            forall |i: nat| (i < a.len() ==> result[i] == a[i]), // Preserves the original elements
            result[a.len()] == b // The last element is the appended value
    {
        let mut result: Vec<i32> = Vec::new();
        let mut i: nat = 0;

        // Append all elements from the input vector
        while i < a.len()
            invariant
                i <= a.len(), // Index is within bounds
                result.len() == i, // The length of the result is equal to the index
                forall |j: nat| (j < i ==> result[j] == a[j]), // Preserves the original elements
            decreases a.len() - i,
        {
            result.push(a[i]); // Append the current element
            i = i + 1; // Move to the next index
        }

        result.push(b); // Append the new value
        result // Return the new vector
    }
}
